#!/bin/bash

set -e

echo "Validating environment variables from .env.test..."
if [ -f ".env.test" ]; then
  while IFS='=' read -r key value || [ -n "$key" ]; do
    # Trim leading/trailing whitespace from key
    key=$(echo "$key" | xargs)

    # Skip empty lines and comments
    if [[ -z "$key" || "$key" == \#* ]]; then
      continue
    fi

    # Remove 'export ' prefix if present
    key=${key#export }

    # Check if the variable is set in the environment
    if [ -n "${!key}" ]; then
      continue
    fi

    # Check if the variable has a value in the file
    value=$(echo "$value" | xargs)
    if [ -z "$value" ]; then
      echo "Error: Required environment variable '$key' is not set in the environment and has no value in .env.test."
      exit 1
    fi
  done < ".env.test"
  echo "Environment validation passed."

  echo "Sending validated config to deployment orchestrator..."
  JSON_PAYLOAD=$(node -e '
const fs = require("fs");
const content = fs.readFileSync(".env.test", "utf8");
const lines = content.split("\n");
const config = {};
for (let line of lines) {
  line = line.trim();
  if (!line || line.startsWith("#")) continue;
  if (line.startsWith("export ")) line = line.substring(7).trim();
  const idx = line.indexOf("=");
  if (idx !== -1) {
    const key = line.substring(0, idx).trim();
    let val = line.substring(idx + 1).trim();
    if ((val.startsWith("\"") && val.endsWith("\"")) || (val.startsWith("\x27") && val.endsWith("\x27"))) {
      val = val.substring(1, val.length - 1);
    }
    config[key] = val;
  }
}
console.log(JSON.stringify(config));
')

  curl -s -X POST -H "Content-Type: application/json" -d "$JSON_PAYLOAD" http://localhost:47301/api/deploy-config
  echo ""
else
  echo "Warning: .env.test not found. Skipping environment validation."
fi

OUTPUT_FILE="release.tar.gz"

echo "Creating release archive: $OUTPUT_FILE..."

# Create tar.gz archive of the current directory
# Exclude node_modules, .git, and the output archive itself
tar -czvf "$OUTPUT_FILE" \
  --exclude="node_modules" \
  --exclude=".git" \
  --exclude="$OUTPUT_FILE" \
  .

echo "Deployment archive '$OUTPUT_FILE' created successfully!"

